#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define STACK_MAX 64

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("ERROR");
        return 0; // exit code not observable
    }

    long stack[STACK_MAX];
    int top = 0;

    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        char *endptr;
        long val = strtol(tok, &endptr, 10);

        if (*endptr == '\0') { // number
            if (top >= STACK_MAX) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
            continue;
        }

        // operator must be a single character
        if (strlen(tok) != 1) {
            puts("ERROR");
            return 0;
        }
        if (top < 2) {
            puts("ERROR");
            return 0;
        }
        long b = stack[--top];
        long a = stack[--top];
        long res;
        switch (tok[0]) {
            case '+': res = a + b; break;
            case '-': res = a - b; break;
            case '*': res = a * b; break;
            case '/':
                if (b == 0) { puts("ERROR"); return 0; }
                res = a / b; break;
            default:
                puts("ERROR");
                return 0;
        }
        if (top >= STACK_MAX) { puts("ERROR"); return 0; }
        stack[top++] = res;
    }

    if (top != 1) {
        puts("ERROR");
        return 0;
    }
    printf("%ld\n", stack[0]);
    return 0;
}
